insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$cuiaba$q$, $q$https://data.queridodiario.ok.org.br/5103403/2011-09-30/8d625a0b494a62722ee5bcd6c633fefbb25df9d3.pdf (Lei 5.463/2011, Gazeta Municipal ed. 1078) ; https://data.queridodiario.ok.org.br/5103403/2012-07-17/c74ee6323a31ab8965b92b59b0cfaaf70162b215.pdf (Decreto 5.207/2012)$q$, $q$Atos oficiais de Cuiabá: domínio público (Lei 9.610/1998, art. 8º, IV). Limite municipal do IBGE só como registro da ZRM desativada; as demais regras ficam sem geometria (desativadas ou revogadas).$q$, 1, $q$Lei 5.463/2011 e Decreto 5.207/2012 (AET). Texto lido por OCR do Querido Diário (portais oficiais bloqueados na pesquisa; falha_de_fonte). Os perímetros da ZRM (art. 4º), da ZAC e da Macrozona Urbana não puderam ser georreferenciados: as quatro regras entram desativadas ou revogadas, sem efeito na rota.$q$);
